async function getJSON(url, fetchFn = fetch) {
  const response = await fetchFn(url)
  if (!response.ok) throw new Error(`HTTP ${response.status}`)
  return response.json()
}
async function getCurrentTemp(lat, lon, fetchFn = fetch) {
  const data = await getJSON(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m`, fetchFn)
  return data.current.temperature_2m
}
async function safeTemp(lat, lon, fetchFn = fetch) {
  try {
    return await getCurrentTemp(lat, lon, fetchFn)
  } catch {
    return null
  }
}
